    /**
     * Method to retrieve the Quote via QuoteFetchOneSummary
     * @param 	summary QuoteFetchOneSummary 
     * @return 	QuoteFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Quote getQuote( QuoteFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "QuoteFetchOneSummary arg cannot be null" );
    	
    	Quote entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Quote
        	// --------------------------------------
        	CompletableFuture<Quote> futureEntity = queryGateway.query(new FindQuoteQuery( new LoadQuoteFilter( summary.getQuoteId() ) ), ResponseTypes.instanceOf(Quote.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Quote with id " + summary.getQuoteId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


